<?php
declare(strict_types=1);
require_once __DIR__.'/../modelo/v2/DeviceLinkV2Service.php';
class RotationResult extends mysqli_result { private array $rows; public function __construct(array $rows){$this->rows=$rows;} public function fetch_assoc(): ?array{return array_shift($this->rows);} public function fetch_all(int $mode=MYSQLI_NUM): array{return $this->rows;} }
class RotationStatement extends mysqli_stmt { private RotationDb $db; private string $sql; private array $params=[]; public function __construct(RotationDb $db,string $sql){$this->db=$db;$this->sql=$sql;} public function bind_param(string $types,&...$vars):bool{$this->params=&$vars;return true;} public function execute(?array $params=null):bool {if($this->db->fail && str_contains($this->sql,'UPDATE op_rh_v2_admin_session'))throw new RuntimeException('simulated');if(str_contains($this->sql,"UPDATE op_rh_v2_admin_pin SET"))$this->db->pin='REVOKED';if(str_contains($this->sql,"UPDATE op_rh_v2_admin_session SET"))$this->db->session='REVOKED';return true;} public function get_result(): mysqli_result|false {if(str_contains($this->sql,'information_schema'))return new RotationResult(in_array($this->params[0],$this->db->tables,true)?[['TABLE_NAME'=>$this->params[0]]]:[]);if(str_contains($this->sql,'FROM op_rh_v2_admin_pin'))return new RotationResult($this->db->pin==='PENDING'?[['id'=>4,'locality_id'=>5,'actor_user_id'=>6]]:[]);if(str_contains($this->sql,'FROM op_rh_v2_admin_session'))return new RotationResult($this->db->session==='ACTIVE'?[['id'=>7,'locality_id'=>5,'actor_user_id'=>6]]:[]);return new RotationResult([]);}public function close():bool{return true;} }
class RotationDb extends mysqli {public array $tables=['op_rh_v2_admin_pin','op_rh_v2_admin_session'];public string $pin='PENDING';public string $session='ACTIVE';public bool $fail=false;public function __construct(){} public function prepare(string $query):mysqli_stmt|false{return new RotationStatement($this,$query);} }
$method=new ReflectionMethod(DeviceLinkV2Service::class,'invalidateAdministrativeSessionsForCredentialRotation');$service=new DeviceLinkV2Service();$pass=0;$fail=0;$assert=function($ok,$name)use(&$pass,&$fail){echo ($ok?'PASS ':'FAIL ').$name.PHP_EOL;$ok?$pass++:$fail++;};
foreach(['0','1'] as $gate){putenv('CHECADOR_ADMIN_PIN_ENABLED='.$gate);$db=new RotationDb();$method->invoke($service,$db,2,1);$assert($db->pin==='REVOKED' && $db->session==='REVOKED',"rotation invalidates PIN and session with gate $gate");putenv('CHECADOR_ADMIN_PIN_ENABLED=1');$method->invoke($service,$db,2,1);$assert($db->session==='REVOKED',"subsequent activation keeps revoked session gate $gate");}
putenv('CHECADOR_ADMIN_PIN_ENABLED=0');$db=new RotationDb();$db->tables=[];$method->invoke($service,$db,2,1);$assert($db->session==='ACTIVE','absent optional admin tables preserve device linking');
putenv('CHECADOR_ADMIN_PIN_ENABLED=1');try{$method->invoke($service,$db,2,1);$ok=false;}catch(RuntimeException $e){$ok=true;}$assert($ok,'enabled feature with absent schema fails closed');
$db=new RotationDb();$db->tables=['op_rh_v2_admin_pin'];try{$method->invoke($service,$db,2,1);$ok=false;}catch(RuntimeException $e){$ok=true;}$assert($ok,'partial schema fails closed');
$db=new RotationDb();$db->fail=true;try{$method->invoke($service,$db,2,1);$ok=false;}catch(RuntimeException $e){$ok=true;}$assert($ok,'persistence error propagates to transaction owner');
echo "RESULT: $pass PASS / $fail FAIL\n";exit($fail?1:0);
